-- =============================================================================
-- 034 : RCP BDPM condensé → matrice_medicaments (Cardio DEUST 2A)
-- Généré par sql/ops/cardio_rcp_matrice_gen.mjs — NE PAS éditer à la main.
-- Matrice / référentiel uniquement ; publications DEUST = source cours (035).
-- EI : fréquents ou rares graves. Idempotent (jp_fill sans doublon).
-- =============================================================================

CREATE OR REPLACE FUNCTION pg_temp.jp_ent(p_table text, p_valeur text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_id uuid; v_norm text := jeupharma.normaliser_valeur(p_valeur);
BEGIN
  EXECUTE format('SELECT id FROM jeupharma.%I WHERE valeur_norm = $1 AND actif LIMIT 1', p_table) INTO v_id USING v_norm;
  IF v_id IS NULL THEN
    EXECUTE format('INSERT INTO jeupharma.%I (valeur, valeur_norm) VALUES ($1, $2) RETURNING id', p_table) INTO v_id USING p_valeur, v_norm;
  END IF;
  RETURN v_id;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_fill(p_matrice uuid, p_champ text, p_vals text[])
RETURNS void LANGUAGE plpgsql AS $$
DECLARE v_tbl text; v_jt text; v_fk text; v_id uuid; i int;
BEGIN
  SELECT t.ent, t.jt, t.fk INTO v_tbl, v_jt, v_fk FROM (VALUES
    ('secteurs','secteurs_therapeutiques','matrice_secteurs_therapeutiques','secteur_therapeutique_id'),
    ('ct','classes_therapeutiques','matrice_classes_therapeutiques','classe_therapeutique_id'),
    ('cp','classes_pharmacologiques','matrice_classes_pharmacologiques','classe_pharmacologique_id'),
    ('ind','indications','matrice_indications','indication_id'),
    ('ci','contre_indications','matrice_contre_indications','contre_indication_id'),
    ('ei','effets_indesirables','matrice_effets_indesirables','effet_indesirable_id'),
    ('pre','precautions_emploi','matrice_precautions_emploi','precaution_emploi_id'),
    ('inter','interactions','matrice_interactions','interaction_id'),
    ('surv','surveillances','matrice_surveillances','surveillance_id'),
    ('noms','noms_commerciaux','matrice_noms_commerciaux','nom_commercial_id')
  ) AS t(champ, ent, jt, fk) WHERE t.champ = p_champ;
  IF v_tbl IS NULL THEN RAISE EXCEPTION 'champ inconnu %', p_champ; END IF;
  IF p_vals IS NULL THEN RETURN; END IF;
  FOR i IN 1 .. coalesce(array_length(p_vals, 1), 0) LOOP
    v_id := pg_temp.jp_ent(v_tbl, p_vals[i]);
    EXECUTE format(
      'INSERT INTO jeupharma.%I (matrice_id, %I, ordre) SELECT $1, $2, $3 WHERE NOT EXISTS (SELECT 1 FROM jeupharma.%I WHERE matrice_id = $1 AND %I = $2)',
      v_jt, v_fk, v_jt, v_fk) USING p_matrice, v_id, i - 1;
  END LOOP;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_matrice_by_norm(p_norm text)
RETURNS uuid LANGUAGE plpgsql AS $$
DECLARE v_m uuid;
BEGIN
  SELECT m.id INTO v_m FROM jeupharma.matrice_medicaments m
  JOIN jeupharma.dcis d ON d.id = m.dci_id
  WHERE d.valeur_norm = jeupharma.normaliser_valeur(p_norm) AND m.statut = 'publie' LIMIT 1;
  IF v_m IS NULL THEN RAISE EXCEPTION 'fiche publie introuvable norm=%', p_norm; END IF;
  RETURN v_m;
END $$;

CREATE OR REPLACE FUNCTION pg_temp.jp_detail_set(p_matrice uuid, p_valeur text)
RETURNS void LANGUAGE plpgsql AS $$
BEGIN
  UPDATE jeupharma.matrice_medicaments
  SET detail_pharmacologie_id = pg_temp.jp_ent('details_pharmacologie', p_valeur), updated_at = now()
  WHERE id = p_matrice;
END $$;

DO $mig$
DECLARE
  m uuid;
BEGIN
-- sels ferreux (CIS 63333712)
  m := pg_temp.jp_matrice_by_norm('sels ferreux');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Antianémique.');
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé dans les cas suivants :', 'Surcharge martiale.', 'Anémie sans carence en fer ou anémie réfractaire.', 'Thalassémie.', 'Insuffisance médullaire.', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['L’hyposidérémie associée aux syndromes inflammatoires n’est pas sensible au traitement martial.', 'Le contrôle de l’efficacité est utile après 3 mois de traitement : il portera sur la correction de l’anémie (Hb, VGM) et sur la restauration des stocks de fer (fer et ferritine sériques).', 'En cas d’intolérance digestive, il est parfois nécessaire de diminuer la posologie, voire d’interrompre provisoirement le traitement.', 'Le traitement doit être suspendu en cas d’épisode diarrhéique aigu, viral ou autre.', 'Le traitement doit également être suspendu dans les jours suivant une transfusion tant que la ferritinémie n’est pas redescendue au-dessous des limites supérieures de la normale (inférieure à 400 µg/l).', 'Ce médicament contient du lactose.', 'Les patients ayant une intolérance héréditaire au galactose, une déficience en lactase de Lapp ou un syndrome de malabsorption du glucose et du galactose ne doivent pas prendre ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', 'Sans objet.', 'Associations déconseillées', '+ Fer (sels de), voie injectable :', 'Lipothymie, voire choc attribué à la libération rapide du fer de sa forme complexe et à la saturation de la sidérophiline.', 'Associations faisant l’objet de précautions d’emploi', '+ Bisphosphonates :', 'Diminution de l’absorption digestive des bisphosphonates.', 'Prendre les sels de fer à distance des bisphosphonates (de 30 minutes au minimum à plus de 2 heures, si possible, selon le biphosphonate).', '+ Calcium :', 'Diminution de l’absorption digestive des sels de fer.', 'Prendre les sels de fer à distance des repas et en l’absence de calcium.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Troubles gastro-intestinaux : état nauséeux, constipation ou diarrhée.', 'Coloration des selles en noir ou gris-noir.', 'Déclaration des effets indésirables suspectés', 'La déclaration des effets indésirables suspectés après autorisation du médicament est importante.', 'Elle permet une surveillance continue du rapport bénéfice/risque du médicament.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Le contrôle de l’efficacité est utile après 3 mois de traitement : il portera sur la correction de l’anémie (Hb, VGM) et sur la restauration des stocks de fer (fer et ferritine sériques).']);

  -- acide ascorbique (CIS 65239674)
  m := pg_temp.jp_matrice_by_norm('acide ascorbique');
  PERFORM pg_temp.jp_detail_set(m, 'VITAMINE C');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement de la carence en vitamine C (scorbut).', 'Traitement d''appoint de l''asthénie fonctionnelle.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à l''un des composants, notamment à la tartrazine, en particulier chez les personnes allergiques à l''aspirine.', 'Lithiases rénales oxalo-calciques pour des doses supérieures à 1g/jour.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Précautions d''emploi', 'En raison d''un effet légèrement stimulant, il est souhaitable de ne pas prendre la vitamine C en fin de journée.', 'Tenir compte de la présence de 41 mg de calcium par cuillère-mesure.', 'Ce médicament contient du saccharose.', 'Son utilisation est déconseillée chez des patients présentant une intolérance au fructose, un syndrome de malabsorption du glucose et du galactose ou un déficit en sucrase/ isomaltase.', 'Ce médicament contient 5,1g de saccharose par cuillère-mesure, dont il faut tenir compte dans la ration journalière en cas de régime pauvre en sucre ou de diabète.', 'Ce médicament contient un agent colorant azoïque (Tartrazine E102) et peut provoquer des réactions allergiques.', 'Chez les sujets porteurs d''un déficit en G6PD, des cas d''hémolyse aiguë ont été rapportés avec des doses d''acide ascorbique supérieures à 1 gramme par jour chez l''adulte.', 'Il est important de respecter les posologies.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['En cas d''hémochromatose, ne donner la vitamine C qu''après avoir commencé le traitement par la deferoxamine.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['A fortes doses supérieures à 1 g/jour, possibilité de:', 'troubles digestifs (brûlures gastriques, diarrhées),', 'troubles urinaires (lithiases oxaliques, cystiniques et uriques),', 'hémolyse chez les sujets déficients en G6PD.']);

  -- cyanocobalamine (CIS 61001031)
  m := pg_temp.jp_matrice_by_norm('cyanocobalamine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ADDITIFS POUR SOLUTIONS INTRAVEINEUSES / VITAMINES');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Supplémentation vitaminique injectable ou pour perfusion chez les patients recevant une nutrition parentérale.', 'Réservé à l’adulte et à l’enfant de plus de 11 ans.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['CERNEVIT ne doit pas être utilisé :', 'Chez le nouveau-né, le nourrisson et l’enfant de moins de 11 ans,', 'En cas d’hypervitaminose à toute vitamine contenue dans cette formulation,', 'En association avec la vitamine A ou les rétinoïdes (voir rubrique 4.5)']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde spéciales', 'Réactions d’hypersensibilité', 'Des réactions allergiques croisées entre les protéines de soja et d’arachides ont été observées.', 'La perfusion ou l’injection doit être immédiatement arrêtée si des signes ou des symptômes d’une réaction d’hypersensibilité se développent.', 'Toxicité des vitamines', 'Cette surveillance est particulièrement importante chez les patients recevant une supplémentation au long cours.', 'Hypervitaminose A :', 'Une maladie hépatique aigüe chez les patients ayant des réserves en vitamine A hépatique saturées peut conduire à la manifestation d’une toxicité de la vitamine A.', 'Hypervitaminose D :', 'Des apports excessifs en vitamine D peuvent provoquer une hypercalcémie et une hypercalciurie.', 'Hypervitaminose E :', 'Bien que très rare, des doses excessives de vitamine E peuvent conduire à un ralentissement de la cicatrisation dû à un dysfonctionnement plaquettaire et des anomalies de la coagulation sanguine.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Les interactions entre certaines vitamines contenues dans CERNEVIT et d’autres agents doivent être gérées de façon appropriée.', 'Ces interactions incluent :', 'Les concentrations plasmatiques des anticonvulsivants doivent être contrôlées en cas d’utilisation concomitante de folates et après l’arrêt des folates.', 'Déferoxamine : augmentation du risque d’insuffisance cardiaque induite par le fer en raison d’une augmentation de la mobilisation du fer par une supplémentation supraphysiologique en vitamine C.', 'Pour les précautions spécifiques, se référer au résumé des caractéristiques du produit de la déferoxamine.', 'Ethionamide : peut entraîner une carence en pyridoxine.', 'Fluoropyrimidines (5-fluorouracile, capécitabine, tégafur) : leur cytotoxicité est augmentée lorsqu’elles sont associées à l’acide folique.', 'Antimétabolites des folates (méthotrexate, raltitrexed) : une supplémentation en acide folique peut diminuer les effets de ces antimétabolites.', 'Antagonistes de la pyridoxine, incluant la cyclosérine, l’hydralazine, l’isoniazide, la pénicillamine, la phénelzine : peut entraîner une carence en pyridoxine.', 'Rétinoïdes, incluant le bexarotène : augmentation du risque de toxicité en cas d’utilisation concomitante de vitamine A (voir rubriques 4.3 et 4.4 : Hypervitaminose A).', 'Solution orale de tipranavir : contient 116 UI/mL de vitamine E, ce qui est au-dessus des apports quotidiens recommandés.', 'Antagonistes de la vitamine K (ex., warfarine) : amélioration de l’effet anticoagulant par la vitamine E.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences des effets indésirables sont décrites selon la convention suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100,', 'Réactions d’hypersensibilité se manifestant par une gêne thoracique, un rash, une urticaire, un érythème, un choc anaphylactique']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Cette surveillance est particulièrement importante chez les patients recevant une supplémentation au long cours.']);

  -- acide folique (CIS 67320915)
  m := pg_temp.jp_matrice_by_norm('acide folique');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : préparation anti-anémique, code ATC : B03BB01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Anémies macrocytaires par carence en acide folique.', 'Troubles chroniques de l''absorption intestinale quelle que soit leur origine.', 'Carences d''apport : malnutrition, éthylisme.', 'Grossesse, en cas de carence prouvée.', 'Néanmoins, le diagnostic anté-natal à la recherche de ce type de malformation reste indispensable.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Les patients présentant une déficience en vitamine B12 ne doivent pas être traités par l’acide folique, à moins que le traitement ne soit administré avec des quantités adéquates d’hydroxocobalamine.', 'En effet, le traitement par acide folique seul peut masquer l’état du patient mais ne traite pas les dommages subaigus et irréversibles causés par la déficience en vitamine B12 sur le système nerveux.', 'L’acide folique ne doit pas être utilisé en cas d’affection maligne, à moins que l’anémie mégaloblastique due à une déficience en acide folique ne représente une complication importante.', 'L’administration d’acide folique chez les patients présentant des tumeurs folate-dépendantes doit être considérée et surveillée avec la plus grande attention.', 'Ce médicament n’est pas destiné aux femmes enceintes en bonne santé à qui il est alors recommandé de prescrire des doses plus faibles.', 'Excipient à effet notoire', 'Ce médicament contient du lactose.', 'Les patients présentant une intolérance au galactose, un déficit total en lactase ou un syndrome de malabsorption du glucose et du galactose (maladies héréditaires rares) ne doivent pas prendre ce médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['+ Antiépileptiques', 'Ces taux peuvent être abaissés au point que les convulsions chez certains patients risquent de ne plus être bien contrôlées.', '+ Antibiotiques', 'Le chloramphénicol et le co-trimoxazole peuvent interférer avec le métabolisme de l’acide folique.', '+ Sulfasalazine', 'La sulfasalazine peut réduire l’absorption de l’acide folique.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquence indéterminée : réaction anaphylactique telle qu’urticaire et angioœdème.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’administration d’acide folique chez les patients présentant des tumeurs folate-dépendantes doit être considérée et surveillée avec la plus grande attention.']);

  -- acide folinique (CIS 60666074)
  m := pg_temp.jp_matrice_by_norm('acide folinique');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Médicament détoxifiant dans un traitement cytostatique, code ATC : V03AF03.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement des cancers colorectaux en association avec le 5-fluorouracile.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active folinate de calcium ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Anémie pernicieuse ou autres anémies dues à une carence en vitamine B12.', 'En cas d’administration concomitante ou de co-prescritpion d’un antimitotique ou d’un cytotoxique : se référer à la rubrique 4.6.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'L’administration de folinate de calcium avec le 5-fluorouracile doit être réalisée uniquement sous la surveillance directe d’un clinicien expérimenté dans l’utilisation des agents de chimiothérapie anti-cancéreuse.', 'Le traitement par le folinate de calcium peut masquer une anémie pernicieuse et d''autres anémies résultant d''une carence en vitamine B12.', 'De nombreux médicaments cytotoxiques inhibiteurs, directs ou indirects, de la synthèse de l’ADN entraînent une macrocytose (hydroxycarbamide, cytarabine, mercaptopurine, thioguanine).', 'Une telle macrocytose ne relève pas d’un traitement par acide folinique.', 'Folinate de calcium/5-fluorouracile :', 'L’acide folinique doit être administré avant le 5- fluorouracile.', 'Administration par voie intraveineuse uniquement.', 'Le folinate de calcium peut potentialiser les risques toxiques du 5-fluorouracile, en particulier chez les personnes âgées et les patients affaiblis.', 'Les manifestations les plus fréquentes sont des leucopénies, des mucites, des stomatites et/ou des diarrhées, qui peuvent être dose-limitantes.', 'Quand le folinate de calcium et le 5-fluorouracile sont utilisés en association, la dose de 5-fluorouracile doit être réduite davantage en cas de toxicité, que lorsque le 5-fluorouracile est utilisé seul.', 'Si des diarrhées et/ou des stomatites surviennent, il est conseillé de réduire les doses de 5-FU jusqu''à disparition complète de ces symptômes.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations faisant l’objet de précautions d’emploi', '+ Phénobarbital, phénytoïne, fosphénytoïne, primidone :', 'Diminution des concentrations plasmatiques des anticonvulsivants inducteurs enzymatiques, par augmentation de leur métabolisme hépatique dont les folates représentent un des cofacteurs.', 'Surveillance clinique, éventuellement des concentrations plasmatiques et adaptation, s’il y a lieu, de la posologie de l’antiépileptique pendant la supplémentation folique et après son arrêt.', 'Associations à prendre en compte', '+ 5 – Fluorouracile, tegafur, capécitabine', 'Potentialisation des effets, à la fois cytostatiques et indésirables, du 5-fluorouracile.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Peu fréquent (0,1-1%) : de la fièvre a été observée après l’administration d’une solution injectable de folinate de calcium.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’administration de folinate de calcium avec le 5-fluorouracile doit être réalisée uniquement sous la surveillance directe d’un clinicien expérimenté dans l’utilisation des agents de chimiothérapie anti-cancéreuse.']);

  -- immunoglobulines anti-d (CIS 62468162)
  m := pg_temp.jp_matrice_by_norm('immunoglobulines anti-d');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Immunsérums et immunoglobulines, Immunoglobuline anti-D (Rh), code ATC : J06BB01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention de l’allo-immunisation fœtomaternelle Rh(D) chez les femmes Rh(D) négatif', 'Prophylaxie antepartum', 'o Prophylaxie antepartum planifiée', 'o Prophylaxie antepartum suite à des complications de la grossesse incluant :', 'Prophylaxie postpartum', 'o Accouchement d''un bébé Rh(D) positif (D, Dfaible, Dpartiel)', 'Une grossesse incompatible Rh(D) est présumée si le fœtus/bébé est Rh(D) positif ou Rh(D) inconnu ou si le père est Rh(D) positif ou Rh(D) inconnu.', 'Traitement des adultes, enfants et adolescents (0-18 ans) Rh(D) négatif après transfusions incompatibles de sang Rh(D) positif ou d''autres produits contenant des globules rouges, par exemple des concentrés plaquettaires.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients de Rhophylac listés en rubrique 6.1.', 'Hypersensibilité aux immunoglobulines humaines.', 'La voie intramusculaire est contre-indiquée chez les sujets présentant une thrombocytopénie sévère ou d''autres troubles de l''hémostase.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['En cas d''utilisation postpartum, l’immunoglobuline anti-Dest destiné à une administration maternelle.', 'Il ne doit pas être administré au nouveau-né.', 'Le produit ne doit pas être utilisé chez les sujets Rh(D) positif, ni chez les personnes déjà immunisées contre l''antigène Rh(D).', 'Hypersensibilité', 'Les réactions allergiques à l''immunoglobuline anti-D peuvent survenir même chez les patients qui ont tolérés les administrations précédentes.', 'Les patients doivent être informés des signes précoces des réactions d’hypersensibilité : urticaire, urticaire généralisé, oppression thoracique, respiration sifflante, hypotension et anaphylaxie.', 'Le traitement requis dépend de la nature et de la gravité de l’effet secondaire.', 'En cas de choc, la prise en charge médicale standard pour le traitement du choc doit être respectée.', 'Si les symptômes de réactions de type allergique ou anaphylactique apparaissent, l’interruption immédiate de l’administration est nécessaire.', 'La concentration d’IgA contenue dans Rhophylac est inférieure à la limite de détection de 5 microgrammes / ml.', 'Néanmoins, le produit peut contenir des quantités infimes d’IgA.', 'Le médecin traitant doit évaluer le bénéfice du traitement avec RHOPHYLAC par rapport aux risques potentiels de réactions d''hypersensibilité.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Vaccins à base de virus vivants atténués', 'Si l''immunoglobuline anti-D doit être administrée, dans les 2 à 4 semaines qui suivent l''administration d''un vaccin à virus vivant atténué, l''efficacité de cette vaccination peut être altérée.', 'Interférence avec les tests sérologiques', 'Après l’injection d’immunoglobuline, l’augmentation transitoire de divers anticorps transférés passivement dans le sang du patient peut être responsable de résultats faux positifs lors de tests sérologiques.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['La fréquence a été évaluée en utilisant les critères suivants : Très fréquent (≥1/10), fréquent (≥1/100 à', 'Hypersensibilité, choc anaphylactique']);

  -- acide acetylsalicylique (CIS 66313736)
  m := pg_temp.jp_matrice_by_norm('acide acetylsalicylique');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTITHROMBOTIQUES/ANTIAGRÉGANTS PLAQUETTAIRES, À L’EXCLUSION DE L’HÉPARINE, Code ATC : B01AC06.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['ACIDE ACETYLSALICYLIQUE BIOGARAN 100 mg, comprimé gastrorésistant est réservé à la prévention secondaire dans le cadre d’un traitement chronique :', 'Prévention secondaire de l’infarctus du myocarde.', 'Prévention de la morbidité cardiovasculaire chez les patients atteints d’angor stable.', 'Antécédents d’angor instable, en dehors de la phase aiguë.', 'Prévention de l’occlusion du greffon après un pontage aorto-coronarien (PAC).', 'Angioplastie coronaire, en dehors de la phase aiguë.', 'Prévention secondaire des accidents ischémiques transitoires (AIT) et des accidents vasculaires cérébraux (AVC), à condition que des hémorragies intracérébrales aient été exclues.', 'ACIDE ACETYLSALICYLIQUE BIOGARAN 100 mg, comprimé gastrorésistant n’est pas recommandé dans les situations d’urgence.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité composés dérivés de l’acide acétylsalicylique ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Dosage de plus de 100 mg par jour : Grossesse, à partir du début du 6ème mois (24 semaines d’aménorrhée) pour des doses d’aspirine supérieures à 100 mg par jour (voir rubrique 4.6).', 'Antécédents d’asthme induit par l’administration d’acétylsalicylates ou de substances ayant une action similaire, en particulier les anti-inflammatoires non stéroïdiens.', 'Ulcère gastroduodénal actif ou antécédents d’ulcère gastroduodénal récurrent et/ou saignements gastriques/intestinaux, ou autres types de saignements, notamment hémorragies vasculaires cérébrales.', 'Diathèse hémorragique ; troubles de la coagulation, notamment hémophilie et thrombocytopénie.', 'Insuffisance hépatique sévère.', 'Insuffisance rénale sévère.', 'Insuffisance cardiaque sévère.', 'Méthotrexate utilisé à des posologies > 15 mg/semaine (voir rubrique 4.5).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Dosage de plus de 100 mg par jour :', 'Risque de mort fœtale', 'Effets chez l’enfant à naitre', 'ACIDE ACETYLSALICYLIQUE BIOGARAN expose également le nouveau-né à un risque d’atteinte rénale (insuffisance rénale), de fermeture prématurée du canal artériel et d’hypertension pulmonaire.', 'Voir rubrique 4.6).', 'ACIDE ACETYLSALICYLIQUE BIOGARAN est contre-indiqué chez la femme enceinte à partir du début du 6ème mois de grossesse (24 semaines d''aménorrhée).', 'En cas de grossesse planifiée ou au cours des 5 premiers mois (avant 24 semaines d''aménorrhée), ACIDE ACETYLSALICYLIQUE BIOGARAN ne doit être prescrit qu’en cas de nécessité absolue.', 'ACIDE ACETYLSALICYLIQUE BIOGARAN 75 mg et 100 mg, comprimé gastrorésistant ne sont pas destinés à être utilisés en tant qu''anti-inflammatoire, analgésique ou antipyrétique.', 'Recommandé pour une utilisation chez les adultes et les adolescents à partir de 16 ans.', 'Ce médicament n''est pas recommandé chez les adolescents/enfants de moins de 16 ans sauf si les bénéfices attendus l''emportent sur les risques.', 'L''acide acétylsalicylique peut être un facteur contribuant à provoquer un syndrome de Reye chez certains enfants.', 'Le syndrome de Reye est une maladie très rare qui affecte le cerveau et le foie et qui peut être d’issue fatale.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations contre-indiquées', '+ Méthotrexate (utilisé à des posologies >15 mg/semaine)', 'Par conséquent, l''association du méthotrexate (à des posologies > 15 mg /semaine) avec ACIDE ACETYLSALICYLIQUE BIOGARAN est contre-indiquée (voir rubrique 4.3).', 'Associations déconseillées', 'Uricosuriques (par exemple probénécide, sulfinpyrazone)', 'Les salicylates inversent l''effet du probénécide et du sulfinpyrazone.', 'L''association doit être évitée.', 'L''administration concomitante d''alcool et d''acide acétylsalicylique augmente le risque de saignements gastro-intestinaux.', 'Associations faisant l''objet de précautions d’emploi ou à prendre en compte', '+ Anticoagulants et thrombolytiques (dérivés de la coumarine comme la warfarine, l’héparine et l’altéplase)', 'Augmentation du risque de saignement due à l''inhibition de la fonction plaquettaire, aux lésions de la muqueuse duodénale et au déplacement des anticoagulants oraux de leurs sites de liaison aux protéines plasmatiques.', 'Le temps de saignement doit être surveillé (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquents de l’acide acétylsalicylique sont des troubles gastro-intestinaux, notamment des nausées et des vomissements.', 'Des hémorragies et des ulcères gastro-intestinaux ont également été observés.', 'Fréquent', '(> 1/100,', 'Peu fréquent', '(> 1/10 000,', 'Thrombopénie, agranulocytose, anémie aplasique']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Dosage de plus de 100 mg par jour :']);

  -- clopidogrel (CIS 67971897)
  m := pg_temp.jp_matrice_by_norm('clopidogrel');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l’agrégation plaquettaire à l’exclusion de l’héparine, code ATC : B01AC-04');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Prévention secondaire des événements athérothrombotiques', 'Le clopidogrel est indiqué :', 'chez les patients adultes souffrant d’un syndrome coronaire aigu :', 'Chez les patients présentant un accident ischémique transitoire (AIT) de risque modéré à élevé ou un accident vasculaire cérébral (AVC) ischémique mineur', 'Le clopidogrel, en association à l’AAS, est indiqué chez :', 'Les patients adultes présentant un AIT de risque modéré à élevé (score ABCD2[1] ≥ 4) ou un AVC ischémique mineur (NIHSS[2] ≤ 3), dans les 24 heures suivant l’AIT ou l’AVC ischémique.', 'Prévention des événements athérothrombotiques et tromboemboliques dans la fibrillation auriculaire', 'Pour plus d’informations, voir rubrique 5.1.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 2 ou à la rubrique 6.1.', 'Insuffisance hépatique sévère.', 'Lésion hémorragique évolutive telle qu’un ulcère gastroduodénal ou une hémorragie intracrânienne.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Saignements et troubles hématologiques', 'Une recherche soigneuse de tout signe de saignement, y compris de saignement occulte, doit être effectuée notamment pendant les premières semaines de traitement et/ou après gestes cardiaques invasifs ou chirurgie.', 'L’administration simultanée de clopidogrel et d’anticoagulants oraux n’est pas recommandée, ces associations pouvant augmenter l’intensité des saignements (voir rubrique 4.5).', 'Dans le cas d’une intervention chirurgicale programmée, si un effet anti-agrégant plaquettaire n’est temporairement pas souhaitable, il convient d’arrêter le traitement par le clopidogrel 7 jours avant l’intervention.', 'Les malades doivent informer leurs médecins et dentistes du traitement par le clopidogrel avant un geste chirurgical programmé et avant la prescription d’un nouveau médicament.', 'Le clopidogrel allonge le temps de saignement et doit donc être utilisé avec prudence chez les patients ayant des lésions susceptibles de saigner (en particulier gastrointestinales et intraoculaires).', 'Purpura thrombopénique thrombotique (PTT)', 'De très rares cas de purpura thrombopénique thrombotique (PTT) ont été rapportés lors de l’utilisation de clopidogrel, parfois après un court délai d’exposition.', 'Cette affection est caractérisée par une thrombopénie et une anémie hémolytique microangiopathique associées à des troubles neurologiques, des troubles de la fonction rénale ou de la fièvre.', 'Le PTT est une affection d’évolution potentiellement fatale qui impose un traitement rapide incluant la plasmaphérèse.', 'Hémophilie acquise', 'Des cas d’hémophilie acquise ont été rapportés lors de l’utilisation de clopidogrel.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Médicaments associés à un risque de saignement', 'Il existe un risque accru de saignement en raison de l''effet additif potentiel.', 'L''administration concomitante de médicaments associés à un risque de saignement doit être réalisée avec prudence.', 'Anticoagulants oraux : l’administration simultanée de clopidogrel et d’anticoagulants oraux n’est pas recommandée, ces associations pouvant augmenter l’intensité des saignements (voir rubrique 4.4).', 'Anti GPIIb/IIIa : le clopidogrel doit être utilisé avec prudence chez les patients traités par anti GPIIb-IIIa (voir rubrique 4.4).', 'Cependant, l’administration simultanée de 500 mg d’AAS deux fois par jour pendant une journée n’a pas modifié de façon significative l’allongement du temps de saignement provoqué par le clopidogrel.', 'Une interaction pharmacodynamique entre le clopidogrel et l’AAS est possible, conduisant à une augmentation du risque de saignement.', 'Par conséquent, l’administration simultanée de ces deux produits devra être entreprise avec prudence (voir rubrique 4.4).', 'Cependant, le clopidogrel et l’AAS ont été administrés en association pendant des durées allant jusqu’à un an (voir rubrique 5.1).', 'Héparine : dans une étude clinique réalisée chez des sujets sains, il n’a pas été nécessaire de modifier la posologie de l’héparine et l’activité de l’héparine sur la coagulation n’a pas été altérée.', 'L’administration simultanée d’héparine n’a pas modifié l’inhibition de l’agrégation plaquettaire due au clopidogrel.', 'Une interaction pharmacodynamique entre le clopidogrel et l’héparine est possible, conduisant à une augmentation du risque de saignement.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Résumé du profil de tolérance', 'La tolérance du clopidogrel a été étudiée chez plus de 44 000 patients ayant participé aux études cliniques dont plus de 12 000 ont été traités pendant un an ou plus.', 'Dans le cadre de l’étude CAPRIE, la tolérance du clopidogrel 75 mg/jour s’est montré globalement comparable à celle de l’AAS 325 mg/jour, indépendamment de l’âge, du sexe et de la race.', 'Les effets indésirables notables au plan clinique qui ont été enregistrés au cours des études CAPRIE, CURE, CLARITY, COMMIT et ACTIVE-A sont présentés ci-après.', 'En plus de l’expérience au cours des études cliniques, des effets indésirables ont été spontanément rapportés.', 'Les saignements sont les effets indésirables les plus fréquemment rapportés tant dans les études cliniques que depuis la mise sur le marché.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Cette affection est caractérisée par une thrombopénie et une anémie hémolytique microangiopathique associées à des troubles neurologiques, des troubles de la fonction rénale ou de la fièvre.']);

  -- prasugrel (CIS 61374393)
  m := pg_temp.jp_matrice_by_norm('prasugrel');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l’agrégation plaquettaire à l’exclusion de l’héparine, code ATC : B01AC22.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Pour plus d''informations, voir rubrique 5.1.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l''un des excipients mentionnés à la rubrique 6.1.', 'Saignement pathologique avéré.', 'Antécédent d''accident vasculaire cérébral ou d''accident ischémique transitoire (AIT).', 'Insuffisance hépatique sévère (classe C de Child-Pugh).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Risque de saignement', 'Dans l''essai clinique de phase III (TRITON), les principaux critères d''exclusion comprenaient un risque accru de saignement ; une anémie ; une thrombocytopénie ; un antécédent de pathologies intracrâniennes.', 'Les patients avec un syndrome coronaire aigu pris en charge par ICP et traités par le prasugrel et AAS ont présenté une augmentation du risque de saignement majeur et mineur selon le système de classification TIMI.', 'Cela s''applique en particulier aux patients :', 'ayant ≥ 75 ans (voir ci-dessous) ;', 'ayant tendance à saigner facilement (par exemple en raison d''un traumatisme récent, d''une intervention chirurgicale récente, d’un saignement gastro-intestinal récent ou récidivant ou d’un ulcère peptique actif) ;', 'Chez les patients qui ont un saignement avéré et pour lesquels une neutralisation de l’effet pharmacologique de PRASUGREL ARROW est nécessaire, une transfusion de plaquettes peut convenir.', 'Ces patients peuvent présenter un risque accru de saignement.', 'Par conséquent, le prasugrel doit être utilisé avec précaution chez ces patients.', 'Risque de saignement associé au moment de l’administration de la dose de charge chez les patients NSTEMI', 'Chirurgie', 'Il doit être conseillé aux patients d’avertir leurs médecins et leurs dentistes qu''ils prennent du prasugrel avant de prévoir une intervention chirurgicale et avant de prendre tout nouveau médicament.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Warfarine', 'L''administration concomitante de PRASUGREL ARROW avec les dérivés coumariniques autres que la warfarine n''a pas été étudiée.', 'Compte tenu de la possibilité de risque accru de saignement, la warfarine (ou les autres dérivés coumariniques) et le prasugrel doivent être co-administrés avec précaution (voir rubrique 4.4).', 'Anti-inflammatoires non stéroïdiens (AINS)', 'L''administration concomitante d’un traitement chronique par AINS n''a pas été étudiée.', 'Compte tenu de la possibilité de risque accru de saignement, les AINS en traitement chronique (y compris les inhibiteurs de la COX-2) et PRASUGREL ARROW doivent être co-administrés avec précaution (voir rubrique 4.4).', 'Effets d''autres médicaments sur PRASUGREL ARROW', 'Acide acétylsalicylique', 'PRASUGREL ARROW doit être administré de manière concomitante avec l''acide acétylsalicylique (AAS).', 'Héparine', 'Un bolus intraveineux unique d''héparine non fractionnée (100 U/kg) n''a pas significativement modifié l''inhibition de l''agrégation plaquettaire induite par le prasugrel.', 'De même, le prasugrel n''a pas significativement modifié l''effet de l''héparine sur les paramètres de la coagulation.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Résumé du profil de sécurité', 'Le taux d''arrêt du médicament de l''étude dû à des événements indésirables a été de 7,2 % pour le prasugrel et de 6,3 % pour le clopidogrel.', 'Parmi ces événements, le saignement a été l''effet indésirable conduisant le plus fréquemment à l''arrêt du traitement avec les deux médicaments à l’étude (2,5 % pour le prasugrel et 1,4 % pour le clopi', 'Saignement', 'Saignement sans rapport avec un pontage coronaire (PC)', 'Dans l’essai TRITON, la fréquence de patients présentant un événement hémorragique sans rapport avec un PC est présentée dans le Tableau 1.']);

  -- ticagrelor (CIS 67382735)
  m := pg_temp.jp_matrice_by_norm('ticagrelor');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : inhibiteurs de l’agrégation plaquettaire autres que l’héparine, code ATC : B01AC24.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['TICAGRELOR ARROW, en association avec l’acide acétylsalicylique (AAS), est indiqué dans la prévention des évènements athérothrombotiques chez les patients adultes ayant :', 'un syndrome coronaire aigu (SCA) ou ;', 'des antécédents d’infarctus du myocarde (IdM) et à haut risque de développer un évènement athérothrombotique (voir rubriques 4.2 et 5.1).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1 (voir rubrique 4.8).', 'Saignement pathologique en cours.', 'Antécédent d’hémorragie intracrânienne (voir rubrique 4.8).', 'Insuffisance hépatique sévère (voir rubriques 4.2, 4.4 et 5.2).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Risque de saignement', 'Si le traitement est cliniquement indiqué, le ticagrélor doit être utilisé avec prudence dans les groupes de patients suivants :', 'Un traitement antifibrinolytique (acide aminocaproïque ou acide tranexamique) et/ou par le facteur VIIa recombinant peuvent améliorer l’hémostase.', 'Le traitement par ticagrélor peut être repris après l’identification de la cause des saignements et leur prise en charge.', 'Chirurgie', 'Il doit être conseillé aux patients d’avertir leurs médecins et leurs dentistes qu’ils prennent du ticagrélor avant de prévoir une intervention chirurgicale et avant de prendre tout nouveau médicament.', 'Si un patient doit avoir une intervention chirurgicale planifiée et que l’effet antiplaquettaire n’est pas souhaité, le ticagrélor doit être arrêté 5 jours avant la chirurgie (voir rubrique 5.1).', 'Patients ayant des antécédents d’accident vasculaire cérébral ischémique', 'Les patients ayant présenté un SCA et ayant des antécédents d''accident vasculaire ischémique peuvent être traités par ticagrélor pendant une durée allant jusqu’à 12 mois (étude PLATO).', 'Dans l’étude PEGASUS, aucun patient ayant des antécédents d’infarctus du myocarde avec accident vasculaire cérébral ischémique antérieur n’a été inclus.', 'Par conséquent, en l’absence de données, la prolongation du traitement au-delà d’un an n’est pas recommandée chez ces patients.', 'Insuffisance hépatique']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Le ticagrélor est essentiellement un substrat du cytochrome CYP3A4 et un inhibiteur faible du CYP3A4.', 'Le ticagrélor est aussi un substrat et un inhibiteur faible de la P-glycoprotéine (P-gp) et il peut augmenter l’exposition aux substrats de la P-gp.', 'Le ticagrélor est un inhibiteur de la protéine de résistance du cancer du sein (BCRP : Breast Cancer Resistance Protein).', 'Effets de certains médicaments ou autres produits sur le ticagrélor', 'Inhibiteurs du CYP3A4', 'Inhibiteurs puissants du CYP3A4 - L’administration concomitante de kétoconazole et de ticagrélor a multiplié par 2,4 la Cmax du ticagrélor et par 7,3 son Aire sous la Courbe (ASC).', 'La Cmax et l’ASC du métabolite actif ont été diminuées de respectivement 89 % et 56 %.', 'Le ticagrélor n’a eu aucun effet sur les concentrations plasmatiques du diltiazem.', 'Les autres inhibiteurs modérés du CYP3A4 (par exemple, amprénavir, aprépitant, érythromycine et fluconazole) auraient probablement des effets similaires et peuvent donc également être coadministrés avec le ticagrélor.', 'Une augmentation d’un facteur 2 de l’exposition au ticagrélor a été observée après une consommation quotidienne de quantités importantes de jus de pamplemousse (3 x 200 mL).', 'Cependant, malgré l’amplitude de cette augmentation de l’exposition, il n’est pas attendu d’impact cliniquement significatif pour la plupart des patients.', 'Inducteurs du CYP3A4']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les catégories de fréquence sont définies selon les conventions suivantes : très fréquent (≥ 1/10), fréquent (≥ 1/100 à Tableau 1 - Effets indésirables par fréquence et classe de système d''organes (CS', 'Très fréquent', 'Fréquent', 'Peu fréquent']);

  -- dipyridamole (CIS 68572748)
  m := pg_temp.jp_matrice_by_norm('dipyridamole');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : AUTRES MEDICAMENTS POUR DIAGNOSTIC, code ATC : V04CX');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Ce médicament est à usage diagnostique uniquement.', 'Explorations fonctionnelles cardiovasculaires :', 'La détection d’une ischémie myocardique se fait idéalement par un test d’effort électrocardiographique accompagné ou non d’une scintigraphie myocardique.', 'L’utilisation de Persantine Injectable est indiquée lorsqu’un test d’effort ne peut être effectué ou n’est pas contributif (bloc de branche gauche).', 'Par ailleurs le test scintigraphique à la Persantine Injectable peut être éventuellement combiné à une épreuve d’effort selon différents protocoles afin d’optimiser la détection de l’ischémie.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Contre-indications communes aux tests de provocation :', 'infarctus récent', 'angor instable', 'sténose serrée du tronc commun connue non pontée', 'troubles du rythme graves non contrôlés', 'insuffisance cardiaque non contrôlée', 'refus du patient', 'Contre-indications spécifiques au dipyridamole :', 'hypotension artérielle systémique (PAS', 'asthme traité', 'hypertension artérielle pulmonaire sévère']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Un test diagnostique se fait au mieux sans traitement antiangineux.', 'La poursuite d’un traitement antiangineux, lors d’un test au dipyridamole associé à une épreuve d’effort sous-maximale, entraîne une baisse de sensibilité du test.', 'Les procédures d’arrêt du traitement doivent être suffisamment prolongées par rapport à la date du rendez-vous de scintigraphie pour tenir compte de la demi-vie biologique des médicaments.', 'L’expérience clinique suggère que les patients traités par dipyridamole oral, qui nécessitent un test d’effort au dipyridamole IV, doivent arrêter les traitements contenant du dipyridamole 24 heures avant le test.', 'Ne pas le faire pourrait altérer la sensibilité du test.', 'Toutes les bases xanthiques (théophylline, théine, caféine ) inhibent l’effet coronarodilatateur du dipyridamole.', 'Un test de vasodilatation ne doit pas être substitué à l’épreuve d’effort classique lorsque celle-ci peut être valablement réalisée chez un patient qui n’a pas de retard d’activation ventriculaire gauche sur l’ECG.', 'L’épreuve doit être interrompue si survient :', 'un effet secondaire grave (cf paragraphe « Effets indésirables »)', 'une chute de la pression artérielle systolique', 'une bradycardie', 'un bloc auriculo-ventriculaire de haut degré']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Le dipyridamole augmente les taux plasmatiques et les effets cardiovasculaires de l’adénosine.', 'Chez les patients déjà traités par le dipyridamole par voie orale, l’expérience clinique suggère que la sensibilité du test au dipyridamole IV peut être altérée.', 'Le traitement oral par le dipyridamole doit être arrêté 24 heures avant le test.', 'Associations faisant l''objet d’une précaution d’emploi', '+ Pentoxifylline', 'Augmentation du risque hémorragique.', 'Renforcer la surveillance clinique et contrôle plus fréquent du temps de saignement.', '+ Bases xanthiques (théophylline, théobromine, caféine) et par analogie aminophylline', 'Réduction de l’effet vasodilatateur du dipyridamole par les bases xanthiques.', 'Eviter la consommation de produits contenant ces bases (café, thé, chocolat ou cola) dans les 24 heures qui précèdent une imagerie myocardique avec le dipyridamole.', 'Interrompre un éventuel traitement par une de ces bases au moins 5 jours avant une imagerie myocardique avec le dypiridamole.', 'Associations à prendre en compte']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très rare : réaction anaphylactique, réaction anaphylactoïde,', 'Très fréquent : céphalées, vertiges', 'Fréquent : paresthésies', 'Très fréquent : douleur thoracique', 'Fréquent : extrasystoles ventriculaires, tachycardie incluant les tachycardies sinusales, arythmie incluant les arythmies ventriculaires', 'Peu fréquent : infarctus du myocarde, bradycardie']);

  -- heparinate de sodium (CIS 64395923)
  m := pg_temp.jp_matrice_by_norm('heparinate de sodium');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Antithrombotique/Héparine, code ATC : B01AB01');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Cette héparine est une héparine classique, dite non fractionnée.', 'Ses indications sont les suivantes :', 'Traitement curatif :', 'o des thromboses veineuses profondes constituées et de l''embolie pulmonaire, à la phase aiguë,', 'o de l''infarctus du myocarde avec ou sans onde Q et de l''angor instable, à la phase aiguë,', 'o des embolies artérielles extracérébrales,', 'o de certains cas de coagulopathie.', 'Prévention des accidents thromboemboliques artériels en cas de cardiopathie emboligène, de thérapeutique endovasculaire et de chirurgie vasculaire artérielle,', 'Prévention de la coagulation dans les circuits de circulation extra-corporelle et d''épuration extra rénale.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Ce médicament ne doit jamais être utilisé dans les situations suivantes :', 'hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'antécédents de thrombopénie grave de type II (thrombopénie induite par l''héparine ou TIH), sous héparine non fractionnée ou sous héparine de bas poids moléculaire (voir rubrique 4.4 - TIH),', 'maladies hémorragiques constitutionnelles,', 'lésion organique susceptible de saigner,', 'manifestations ou tendances hémorragiques liées à des troubles de l''hémostase: les coagulopathies peuvent être une exception à cette règle (voir rubrique 4.1) à condition qu''elles ne compliquent pas une TIH,', 'hémorragie intracérébrale,', 'enfant prématuré ou nouveau-né (contient de l''alcool benzylique).', 'Une anesthésie péridurale ou une rachianesthésie ne doivent jamais être effectuées pendant un traitement par héparine.', 'Ce médicament est GENERALEMENT DECONSEILLE en cas de :', 'accident vasculaire cérébral ischémique étendu à la phase aiguë, avec ou sans troubles de la conscience.', 'Lorsque l''accident vasculaire cérébral est d''origine embolique, le délai est de 72 heures.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Devant un patient sous héparine (à dose curative ou préventive) qui présente un événement thrombotique, tel que :', 'un accident vasculaire cérébral ischémique,', 'un infarctus du myocarde,', 'une ischémie aiguë des membres inférieurs,', 'une embolie pulmonaire,', 'une phlébite,', 'une aggravation de la thrombose pour laquelle il est traité.', 'Il faut systématiquement penser à une thrombopénie induite par l''héparine (TIH) et faire pratiquer en urgence une numération des plaquettes (voir rubrique 4.4).', 'Situations à risque', 'La surveillance du traitement sera renforcée en cas d''antécédents d''ulcères digestifs, de maladies vasculaires de la choriorétine ou en période postopératoire après chirurgie du cerveau et de la moelle épinière.', 'La ponction lombaire devra être discutée en tenant compte du risque de saignement intrarachidien.', 'Elle devra être différée chaque fois que possible.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Quelle que soit la dose d’héparine :', '+ Défibrotide', 'Risque hémorragique accru.', 'Avec des doses curatives d’héparine et/ou chez le sujet âgé :', 'Utiliser un autre anti-inflammatoire ou un autre analgésique ou antipyrétique.', '+ Anti-inflammatoires non stéroïdiens (A.I.N.S.)', 'Augmentation du risque hémorragique (agression de la muqueuse gastro-duodénale par les anti-inflammatoires non stéroïdiens).', 'Si l''association ne peut être évitée, surveillance clinique étroite.', '+ Dextran 40', 'Augmentation du risque hémorragique (inhibition des fonctions plaquettaires par le dextran 40).', 'Associations faisant l''objet de précautions d’emploi']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Des hémorragies surrénaliennes, entraînant une insuffisance surrénalienne aiguë, ont été observées au cours d''un traitement anticoagulant.', 'Par conséquent, ce traitement doit être interrompu chez les patients qui présentent des signes et des symptômes d''hémorragie surrénalienne et d''insuffisance surrénalienne aiguë.', 'o les plus fréquentes, de type I, sont habituellement modérées (>100 000), précoces (avant le cinquième jour) et ne nécessitent pas l''arrêt de l''héparine,', 'De rares nécroses cutanées au point de perfusion, ont été signalées avec les héparines.', 'De rares manifestations d''hypersensibilité notamment urticaire, conjonctivite, rhinite, asthme, cyanose, tachypnée, sensations d''oppression, fièvre, frissons, œdème angio-neurotique, et rarement choc ']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['La surveillance du traitement sera renforcée en cas d''antécédents d''ulcères digestifs, de maladies vasculaires de la choriorétine ou en période postopératoire après chirurgie du cerveau et de la moelle épinière.']);

  -- heparinate de calcium (CIS 69636132)
  m := pg_temp.jp_matrice_by_norm('heparinate de calcium');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Antithrombotiques, code ATC : B01AB01.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Cette héparine est une héparine classique, dite non fractionnée.', 'Ses indications sont les suivantes :', 'Traitement :', 'o Des thromboses veineuses profondes constituées et de l''embolie pulmonaire, à la phase aiguë.', 'o De l''infarctus du myocarde avec ou sans onde Q et de l''angor instable, à la phase aiguë.', 'o Des embolies artérielles extracérébrales.', 'Prévention des accidents thromboemboliques veineux :', 'o En milieu chirurgical.', 'o Chez les patients alités, présentant une affection médicale aiguë (notamment en post-infarctus, en cas d''insuffisance cardiaque, après un accident vasculaire cérébral ischémique avec paralysie des membres inférieurs).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Quelles que soient les doses (curatives ou préventives), ce médicament NE DOIT PAS ETRE PRESCRIT dans les situations suivantes :', 'o Hypersensibilité à l''héparine ou à l’un des excipients mentionnés à la rubrique 6.1.', 'o Antécédents de thrombopénie grave de type II (thrombopénie induite par l''héparine ou TIH), sous héparine non fractionnée ou sous héparine de bas poids moléculaire (voir rubrique 4.4 - TIH).', 'o Maladies hémorragiques constitutionnelles ;', 'o En cas de traitement par anticoagulants oraux d’action directe AOD (apixaban, edoxaban, rivaroxaban, etc.) (voir rubrique 4.5).', 'A dose curative, dans les situations suivantes :', 'o Lésion organique susceptible de saigner.', 'o Manifestations ou tendances hémorragiques liées à des troubles de l''hémostase.', 'o Hémorragie intracérébrale.', 'o De plus, une anesthésie péridurale ou une rachianesthésie ne doivent jamais être effectuées durant un traitement par héparine à dose curative.', 'A dose curative, ce médicament est GENERALEMENT DECONSEILLE en cas d'' :', 'o Accident vasculaire cérébral ischémique étendu à la phase aiguë, avec ou sans troubles de la conscience.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Mises en garde', 'Devant un patient sous héparine (à dose curative ou préventive) qui présente un événement thrombotique, tel que :', 'Un accident vasculaire cérébral ischémique.', 'Un infarctus du myocarde.', 'Une ischémie aiguë des membres inférieurs.', 'Une embolie pulmonaire.', 'Une phlébite.', 'Une aggravation de la thrombose pour laquelle il est traité.', 'Il faut systématiquement penser à une thrombopénie induite par l''héparine (TIH) et faire pratiquer en urgence une numération des plaquettes (voir rubrique « Précautions d''emploi »).', 'En cas de rachianesthésie l''injection de la dose d''héparine préventive doit se faire 6 heures après que les cathéters intra-rachidiens aient été enlevés.', 'Le rapport bénéfice risque de l''administration de faible dose d''héparine avant une anesthésie loco-régionale intrathécale ou périmédullaire doit être évalué pour chaque patient.', 'Le risque de survenue d''un hématome périmédullaire dépend de la technique utilisée et de l''expérience de l''opérateur.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Association contre-indiquée', 'Quelque soit la dose d’héparine :', '+ Anticoagulants oraux type AOD (apixaban, edoxaban, rivaroxaban, etc.)', 'Augmentation du risque hémorragique.', 'Les anticoagulants oraux d’action directe ne doivent pas être administrés conjointement à l’héparine.', 'Lors du relais de l’un par l’autre, respecter l’intervalle entre les prises.', 'Associations déconseillées', '+ Défibrotide', 'Risque hémorragique accru.', 'Avec des doses curatives d’héparine et/ou chez le sujet âgé :', 'Utiliser un autre anti-inflammatoire ou un autre antalgique ou antipyrétique.', '+ Anti-inflammatoires non stéroïdiens (A.I.N.S.)']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Très fréquent', 'Fréquent', '≥ 1/100 to', 'Peu fréquent', '≥ 1/10 000 to']);

  -- dalteparine (CIS 61540502)
  m := pg_temp.jp_matrice_by_norm('dalteparine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Anti-thrombotiques, code ATC : B01AB04.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Cette héparine est une héparine de bas poids moléculaire (HBPM).', 'Ses indications sont les suivantes:', 'Population adulte', 'Traitement curatif des thromboses veineuses profondes (TVP) constituées ;', 'Traitement de l''angor instable et de l''infarctus du myocarde sans onde Q à la phase aiguë, en association avec l''aspirine;', 'Prévention de la coagulation du circuit de circulation extracorporelle au cours de l''hémodialyse (séance en général d''une durée ≤ 4 heures).', 'Population pédiatrique', 'Traitement de la thromboembolie veineuse (TEV) symptomatique chez les patients pédiatriques âgés de 1 mois et plus.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Quelles que soient les doses (curatives ou préventives), ce médicament NE DOIT PAS ETRE UTILISE dans les situations suivantes :', 'hypersensibilité à la daltéparine sodique, à d’autres héparines de bas poids moléculaire, héparines ou à l’un des excipients mentionnés à la rubrique 6.1 Liste des excipients,', 'lésion organique susceptible de saigner,', 'ulcère gastro-duodénal aigu,', 'hémorragie intracérébrale ou autre hémorragie active,', 'troubles sévères de la coagulation,', 'endocardite infectieuse aiguë ou subaiguë,', 'lésions ou interventions chirurgicales au niveau du système nerveux central, des yeux ou des oreilles,', 'en cas de traitement par anticoagulants oraux d’action directe AOD (apixaban, edoxaban, rivaroxaban, etc.) (voir rubrique 4.5).', 'A dose curative, ce médicament NE DOIT PAS ETRE UTILISE dans les cas suivants :', 'en l''absence de données, insuffisance rénale sévère (définie par une clairance de la créatinine de l''ordre de 30 mL/min selon l''estimation de la formule de Cockroft), en dehors de l''indication au cours de l''hémodialyse.', 'Dans l''insuffisance rénale sévère, utiliser l''héparine non fractionnée.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Bien que les différentes spécialités d''héparines de bas poids moléculaire aient toutes des concentrations exprimées en unités internationales anti-Xa, leur efficacité ne se limite pas qu''à cette activité anti-Xa.', 'Il serait dangereux de substituer le schéma posologique d''une HBPM par celui d''une autre HBPM ou par celui d''un autre polysaccharide de synthèse, chaque schéma ayant été validé par des études cliniques spécifiques.', 'Il y a donc lieu d''être particulièrement vigilant et de respecter le mode d''emploi spécifique de chacune des spécialités.', 'FRAGMINE ne doit pas être injecté par voie intramusculaire.', 'En raison du risque d’hématome, l’injection intramusculaire d’autres médicaments doit être évitée quand la dose quotidienne de daltéparine sodique est supérieure à 5 000 UI', 'Mises en garde spéciales', 'La prudence est recommandée en cas de thrombopénie et d’anomalie de la fonction plaquettaire, d’insuffisance hépatique et rénale sévères, d’hypertension non-contrôlée, de rétinopathie hypertensive ou diabétique.', 'Risque hémorragique', 'Il est impératif de respecter les schémas thérapeutiques recommandés (posologies et durées de traitement).', 'Dans le cas contraire, des accidents hémorragiques peuvent s''observer, surtout chez les sujets à risque (sujets âgés, insuffisants rénaux...).', 'Les accidents hémorragiques graves ont notamment été observés :', 'chez le sujet âgé, notamment du fait de la détérioration de la fonction rénale liée à l''âge, y compris à l’intérieur de la fourchette thérapeutique,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['INDEPENDAMMENT DE L’INDICATION', 'Médicaments augmentant les effets de la daltéparine', 'Association contre-indiquée', '+ Anticoagulants oraux type AOD (apixaban, edoxaban, rivaroxaban, etc.)', 'Augmentation du risque hémorragique.', 'Les anticoagulants oraux d’action directe ne doivent pas être administrés conjointement à l’héparine.', 'Lors du relais de l’un par l’autre, respecter l’intervalle entre les prises.', 'Association déconseillée', '+ Défibrotide', 'Risque hémorragique accru.', 'Associations faisant l''objet de précautions d’emploi', '+ Anticoagulants oraux de type antivitamine K']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent', 'Peu fréquent']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['chez le sujet âgé, notamment du fait de la détérioration de la fonction rénale liée à l''âge, y compris à l’intérieur de la fourchette thérapeutique,']);

  -- enoxaparine sodique (CIS 66760541)
  m := pg_temp.jp_matrice_by_norm('enoxaparine sodique');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : agents antithrombotiques, groupe de l’héparine ; code ATC : B01AB05.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['ENOXAPARINE ARROW 10 000 UI (100 mg)/1 mL, solution injectable en seringue préremplie est indiqué chez l’adulte dans :', 'Le traitement prophylactique de la maladie thromboembolique veineuse en chirurgie à risque modéré et élevé, en particulier en chirurgie orthopédique ou générale, dont la chirurgie oncologique.', 'Le traitement de la thrombose veineuse profonde (TVP) et de l’embolie pulmonaire (EP), à l’exclusion de l’EP susceptible de relever d’un traitement thrombolytique ou chirurgical.', 'Le traitement prolongé de la thrombose veineuse profonde (TVP) et de l''embolie pulmonaire (EP) et la prévention de leur(s) récidive(s) chez les patients atteints d''un cancer actif.', 'La prévention de la formation d’un thrombus dans le circuit de circulation extracorporelle au cours de l’hémodialyse.', 'Le syndrome coronaire aigu :', 'o Traitement de l’angor instable et de l’infarctus du myocarde sans élévation du segment ST (NSTEMI), administré en association avec l’acide acétylsalicylique par voie orale.', 'o Traitement de l’infarctus du myocarde aigu avec élévation du segment ST (STEMI), incluant les patients éligibles à un traitement médical ou à une intervention coronaire percutanée (ICP) secondaire.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['L’énoxaparine sodique est contre-indiquée chez les patients présentant :', 'Une l’hypersensibilité à l’énoxaparine sodique, à l’héparine ou à ses dérivés, y compris à d’autres héparines de bas poids moléculaire (HBPM), ou à l’un des excipients mentionnés dans la rubrique 6.1.', 'Un antécédent de thrombopénie induite par héparine (TIH) à médiation immunitaire au cours des 100 derniers jours ou en présence d’anticorps circulants (voir également la rubrique 4.4).', 'Rachianesthésie ou anesthésie péridurale ou locorégionale lorsque l’énoxaparine sodique est utilisée pour un traitement curatif dans les 24 heures précédentes (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Généralités', 'L’énoxaparine sodique n’est pas interchangeable (unité pour unité) avec d’autres HBPM.', 'Ces médicaments diffèrent par leurs procédés de fabrication, leurs poids moléculaires, leurs activités anti-Xa et anti-IIa spécifiques, leurs unités, leurs posologies et leur efficacité clinique et sécurité d’emploi.', 'Cela se traduit par des différences au niveau de leurs propriétés pharmacocinétiques et activités biologiques associées (par ex., activité antithrombine et interactions avec les plaquettes).', 'Par conséquent, une attention particulière et un respect des règles de bon usage spécifiques à chaque médicament sont nécessaires.', 'Antécédents de TIH (> 100 jours)', 'L’utilisation d’énoxaparine sodique chez les patients ayant des antécédents de TIH à médiation immunitaire au cours des 100 derniers jours ou en présence d’anticorps circulants est contre-indiquée (voir rubrique 4.3).', 'Les anticorps circulants peuvent persister plusieurs années.', 'L’énoxaparine sodique doit être utilisée avec une extrême prudence chez les patients ayant des antécédents (> 100 jours) de thrombopénie induite par héparine sans anticorps circulants.', 'Surveillance de la numération plaquettaire', 'Chez les patients atteints d''un cancer avec une numération plaquettaire inférieure à 80 g/L, un traitement anticoagulant ne peut être envisagé qu''au cas par cas et une surveillance étroite est recommandée.', 'Le risque de TIH médiée par des anticorps existe également avec les HBPM.']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Associations déconseillées', 'Médicaments modifiant l’hémostase (voir rubrique 4.4)', 'Il est recommandé d’arrêter certains médicaments qui modifient l’hémostase avant un traitement par énoxaparine sodique, à moins que cela ne soit strictement indiqué.', 'Si l’association est indiquée, l’énoxaparine sodique doit être utilisée sous surveillance clinique et biologique étroite, lorsque nécessaire.', 'Ces médicaments incluent :', 'o les salicylés systémiques, l’acide acétylsalicylique à des doses anti-inflammatoires et les AINS, y compris le kétorolac ;', 'o les thrombolytiques (par ex., altéplase, rétéplase, streptokinase, ténectéplase, urokinase) et anticoagulants (voir rubrique 4.2).', 'Associations faisant l''objet de précautions d’emploi', 'Les médicaments suivants peuvent être administrés avec prudence en association avec l’énoxaparine sodique :', 'Autres médicaments modifiant l’hémostase, tels que :', 'o le Dextran 40 ;', 'o les glucocorticoïdes systémiques.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Dans les études cliniques, les hémorragies, la thrombopénie et la thrombocytose étaient les effets les plus fréquemment rapportés (voir rubrique 4.4 et « Description d’effets indésirables sélectionnés', 'Les fréquences sont déterminées de la façon suivante : très fréquent (≥ 1/10) ; fréquent (≥ 1/100, Affections hématologiques et du système lymphatique', 'Fréquent : hémorragie, anémie hémorragique*, thrombopénie, thrombocytose', 'Fréquent : réaction allergique', 'Rare : réactions anaphylactiques/anaphylactoïdes, y compris choc*']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Surveillance de la numération plaquettaire', 'Chez les patients atteints d''un cancer avec une numération plaquettaire inférieure à 80 g/L, un traitement anticoagulant ne peut être envisagé qu''au cas par cas et une surveillance étroite est recommandée.']);

  -- tinzaparine (CIS 67167017)
  m := pg_temp.jp_matrice_by_norm('tinzaparine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : Agents antithrombotiques, groupe héparine, code ATC : B01AB10.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement des thromboses veineuses et de la maladie thromboembolique incluant les thromboses veineuses profondes et les embolies pulmonaires chez les adultes.', 'Pour certains patients atteints d’une embolie pulmonaire (par exemple ceux présentant une instabilité hémodynamique sévère) un traitement alternatif, comme la chirurgie ou la thrombolyse, peut être indiqué.', 'Traitement prolongé de la maladie thromboembolique veineuse et prévention de ses récidives chez les patients adultes atteints d’un cancer actif.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1.', 'Thrombopénie induite par l’héparine d’origine immune (type II) ou antécédents de thrombopénie induite par l’héparine d’origine immune (voir rubrique 4.4).', 'Hémorragie majeure active ou pathologies prédisposant à des hémorragies majeures.', 'L''hémorragie majeure est définie comme une hémorragie satisfaisant l''un des trois critères suivants :', 'provoque une chute du taux d’hémoglobine de 20 g/l (1,24 mmol/l) ou supérieure, ou', 'entraîne la transfusion d’au moins deux unités de sang total ou de globules rouges.', 'Endocardite septique.', 'Les doses thérapeutiques d’innohep (175 UI/kg) sont contre-indiquées chez les patients sous anesthésie neuraxiale.', 'Si une anesthésie neuraxiale est prévue, innohep doit être interrompu au moins 24 heures avant l’intervention.', 'Innohep ne doit pas être réadministré avant au moins 4 à 6 heures après l’exécution de l''anesthésie spinale ou après que le cathéter ait été retiré.', 'Les signes et symptômes d’une lésion neurologique doivent être étroitement surveillés chez les patients.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Hémorragie', 'La prudence est recommandée en cas d’administration d’innohep à des patients à risque hémorragique.', 'Pour les patients à risque d’hémorragie majeure, voir rubrique 4.3.', 'L’association à des médicaments affectant la fonction plaquettaire ou le système de coagulation doit être évitée ou étroitement surveillée (voir rubrique 4.5).', 'Injections intramusculaires', 'Innohep ne doit pas être injecté par voie intramusculaire du fait du risque d’hématome.', 'Compte tenu du risque d’hématome, les injections intramusculaires concomitantes doivent également être évitées.', 'Thrombopénie induite par l’héparine', 'Une numération plaquettaire doit être pratiquée avant le début du traitement et renouvelée régulièrement ensuite compte tenu du risque de thrombopénie d’origine immunologique induite par l’héparine (type II).', 'Le traitement par innohep doit être interrompu chez les patients développant une thrombopénie d’origine immunologique induite par l’héparine (type II) (voir rubriques 4.3 et 4.8).', 'La numération plaquettaire se normalise généralement dans les 2 à 4 semaines suivant l’interruption.', 'Hyperkaliémie']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Ces associations doivent être évitées ou minutieusement surveillées (voir rubrique 4.4).']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les effets indésirables les plus fréquemment rapportés sont des hémorragies, une anémie consécutive à une hémorragie et des réactions sur le site d’injection.', 'Les hémorragies peuvent toucher n’importe quel organe et présenter différents degrés de gravité.', 'Bien que les hémorragies majeures soient peu courantes, des cas de décès ou de handicap permanent ont été rapportés.', 'Elles incluent de rares cas de nécrose de la peau, d’éruption cutanée toxique (par exemple, le syndrome de Stevens-Johnson), un angioedème et une anaphylaxie.']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['L’association à des médicaments affectant la fonction plaquettaire ou le système de coagulation doit être évitée ou étroitement surveillée (voir rubrique 4.5).', 'Hyperkaliémie']);

  -- nadroparine (CIS 69766923)
  m := pg_temp.jp_matrice_by_norm('nadroparine');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTI-THROMBOTIQUES, code ATC : B01AB06.');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Cette héparine est une héparine de bas poids moléculaire (HBPM).', 'Ses indications sont les suivantes :', 'prophylaxie des troubles thrombo-emboliques, notamment :', 'o maladie thrombo-embolique veineuse en chirurgie, dans les situations à risque modéré ou élevé ;', 'prévention de la coagulation du circuit de circulation extracorporelle au cours de l’hémodialyse (séance en général d''une durée ≤ 4 heures) ;', 'traitement curatif des thromboses veineuses profondes constituées ;', 'traitement de l’angor instable et de l’infarctus du myocarde sans onde Q à la phase aiguë, en association avec l’aspirine.']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['La nadroparine est contre-indiquée dans les situations suivantes :', 'hypersensibilité à la nadroparine, à l''héparine ou à ses dérivés, y compris les autres héparines de bas poids moléculaire,', 'ou à l''un des excipients mentionnés à la rubrique 6.1 ;', 'lésion organique susceptible de saigner (telle qu''un ulcère gastroduodénal évolutif) ;', 'accident vasculaire cérébral hémorragique,', 'en l''absence de données, en cas d''insuffisance rénale sévère (définie par une clairance de la créatinine', 'de plus, une anesthésie péridurale, ou une rachianesthésie ne doivent jamais être effectuées lors d''un traitement curatif par HBPM,', 'les formes multidoses contiennent de l''alcool benzylique, et ne devraient donc pas être utilisées chez les enfants âgés de moins de 3 ans,', 'endocardite infectieuse aiguë (en dehors de certaines cardiopathies emboligènes).', 'A dose curative, ce médicament est GÉNÉRALEMENT DECONSEILLE dans les cas suivants :', 'accident vasculaire cérébral ischémique étendu à la phase aiguë, avec ou sans troubles de la conscience.', 'Lorsque l''accident vasculaire cérébral est d''origine embolique, le délai à respecter est de 72 heures.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Bien que les différentes spécialités d''héparines de bas poids moléculaire aient toutes des concentrations exprimées en unités internationales anti-Xa, leur efficacité ne se limite pas qu''à cette activité anti-Xa.', 'II serait dangereux de substituer le schéma posologique d''une HBPM par celui d''une autre HBPM ou par celui d''un autre polysaccharide de synthèse, chaque schéma ayant été validé par des études cliniques spécifiques.', 'II y a donc lieu d''être particulièrement vigilant et de respecter le mode d''emploi spécifique de chacune des spécialités.', 'Mises en garde spéciales', 'Risque hémorragique', 'II est impératif de respecter les schémas thérapeutiques recommandés (posologies et durées de traitement).', 'Dans le cas contraire, des accidents hémorragiques peuvent s''observer, surtout chez les sujets à risque (sujets âgés, insuffisants rénaux).', 'Les accidents hémorragiques graves ont notamment été observés :', 'chez le sujet âgé, notamment du fait de la détérioration de la fonction rénale liée à l''âge,', 'en cas d''insuffisance rénale,', 'en cas de poids inférieur à 40 kg,', 'en cas de traitement prolongé au-delà de la durée moyenne préconisée de 10 jours,']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['La survenue d''une hyperkaliémie peut dépendre de l''existence de facteurs de risque associés.', 'Ce risque est majoré en cas d''association des médicaments sus-cités.', 'Associations déconseillées', 'Chez le sujet de moins de 65 ans aux doses curatives d’HBPM, et chez le sujet âgé (> 65 ans) quelle que soit la dose d’HBPM.', 'Augmentation du risque hémorragique (inhibition de la fonction plaquettaire et agression de la muqueuse gastro-duodénale par les salicylés et les A.l.N.S).', 'Utiliser un analgésique antipyrétique non salicylé (type paracétamol).', 'Si l’association avec les A.l.N.S ne peut être évitée, une surveillance clinique étroite est recommandée.', '+ Dextran 40 (voie parentérale)', 'Augmentation du risque hémorragique (inhibition de la fonction plaquettaire par le Dextran 40).', 'Associations faisant l''objet de précautions d’emploi', '+ Anticoagulants oraux', 'La nadroparine doit être administrée avec précaution chez les patients recevant des anticoagulants oraux, du fait de la potentialisation de l''action anticoagulante par cette association.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Les fréquences des effets indésirables (de très fréquent à très rare) ont été déterminées par les données de très nombreux essais cliniques.', 'très fréquent : ≥ 1/10', 'fréquent : ≥ 1/100 ;', 'peu fréquent : ≥1/1000 ;', 'rare : ≥ 1/10000 ;', 'Très fréquent : manifestations hémorragiques pouvant toucher différents sites, qui surviennent essentiellement en présence :']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['chez le sujet âgé, notamment du fait de la détérioration de la fonction rénale liée à l''âge,']);

  -- danaparoide (CIS 69449143)
  m := pg_temp.jp_matrice_by_norm('danaparoide');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : ANTITHROMBOTIQUE/GROUPE DE L''HEPARINE, code ATC : B01AB09 (B : sang et organes hématopoïétiques).');
  PERFORM pg_temp.jp_fill(m, 'ind', ARRAY['Traitement prophylactique de la maladie thrombo-embolique en chirurgie oncologique et orthopédique.', 'Traitement curatif des manifestations thrombo-emboliques chez les patients ayant des antécédents documentés de TIH et nécessitant un traitement antithrombotique curatif par voie parentérale.', 'Traitement curatif de la TIH aigüe (avec ou sans thrombose).']);
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Affection hémorragique grave, par exemple hémophilie et purpura thrombocytopénique idiopathique, sauf si le patient présente une TIH et qu''il n''existe aucune alternative thérapeutique,', 'Accident vasculaire cérébral hémorragique à la phase aiguë dans les trois derniers mois,', 'Situation hémorragique non contrôlable,', 'Insuffisance rénale ou hépatique sévères, sauf si le patient présente une TIH et qu''il n''existe aucune alternative thérapeutique,', 'Hypertension artérielle sévère non contrôlée, avec notamment rétinopathie grave,', 'Ulcère gastroduodénal évolutif, sauf si cet ulcère est la cause de l''intervention chirurgicale,', 'Rétinopathie diabétique,', 'Endocardite bactérienne aiguë,', 'Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1,', 'Test d''agrégation plaquettaire in vitro positif en présence de danaparoïde chez les patients ayant des antécédents de thrombopénie induite par l''héparine ou par un anticoagulant apparenté,', 'Chez les patients recevant du danaparoïde sodique pour un traitement curatif plutôt que prophylactique, l’anesthésie loco-régionale lors des interventions chirurgicales est contre-indiquée,', 'Hypersensibilité aux sulfites.']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Ce produit ne doit pas être administré par voie intramusculaire.', 'Ce médicament contient du « sulfite » et peut provoquer des réactions allergiques sévères et un bronchospasme.', 'Ce médicament contient du sodium.', 'Le taux de sodium est inférieur à 1 mmol par ampoule, c’est à dire « sans sodium ».', 'Réactivité croisée du danaparoïde sodique', 'L’incidence d’une réactivité sérologique croisée du danaparoïde avec un anticorps induit par l’héparine avant le début du traitement est d’environ 5%.', 'Afin de limiter ce risque :', 'un test d''agrégation plaquettaire avec le danaparoïde devra si possible être pratiqué avant l''instauration du traitement afin de vérifier l''absence de réaction croisée in vitro.', 'Le traitement pourra cependant être entrepris sans attendre le résultat de ce test.', 'Mais il devra être arrêté si le test revient positif,', 'au moindre doute, pratiquer un test de réactivité croisée in vitro.', 'Risque hémorragique']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['Il n’existe pas de donnée disponible sur l’effet du danaparoïde sur les tests de la fonction thyroïdienne.', 'Les études d’interaction n’ont été réalisées que chez l’adulte.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Fréquent (³1/100,', 'Peu Fréquent (³1/1000,', 'Rare (³1/10000,', 'Thrombocytopénie*, thrombocytopénie induite par l’héparine', 'Thrombocytopénie auto immune']);

  -- fondaparinux (CIS 66565534)
  m := pg_temp.jp_matrice_by_norm('fondaparinux');
  PERFORM pg_temp.jp_detail_set(m, 'Classe pharmacothérapeutique : agent antithrombotique, code ATC : B01AX05');
  PERFORM pg_temp.jp_fill(m, 'ci', ARRAY['Hypersensibilité à la substance active ou à l’un des excipients mentionnés à la rubrique 6.1', 'Saignement évolutif cliniquement significatif', 'Endocardite bactérienne aiguë', 'Insuffisance rénale sévère (clairance de la créatinine < 30 ml/min).']);
  PERFORM pg_temp.jp_fill(m, 'pre', ARRAY['Voie sous cutanée uniquement.', 'Le fondaparinux ne doit pas être injecté par voie intramusculaire.', 'Hémorragie', 'Ces traitements comprennent : désirudine, agents fibrinolytiques, antagonistes du récepteur GP IIb/IIIa, héparine, héparinoïdes ou Héparines de Bas Poids Moléculaire (HBPM).', 'Lors du traitement d’évènements thromboemboliques veineux, un traitement concomitant par antivitamine K sera administré selon les modalités définies à la rubrique 4.5.', 'Les autres médicaments antiagrégants plaquettaires (acide acétylsalicylique, dipyridamole, sulfinpyrazone, ticlopidine ou clopidogrel) et les AINS doivent être utilisés avec précaution.', 'Si l''association ne peut être évitée, une surveillance particulière s''impose.', 'Rachianesthésie/anesthésie péridurale', 'Sujets âgés', 'Les sujets âgés présentent un risque accru de saignement.', 'Chez les patients de moins de 65 ans, de 65 à 75 ans et de plus de 75 ans, traités aux doses recommandées pour des TVP ou des EP, l’incidence des hémorragies était respectivement de 3,0 %, 4,5 % et 6,5 %.', 'Chez les patients âgés, le fondaparinux doit être utilisé avec précaution (voir rubrique 4.2).']);
  PERFORM pg_temp.jp_fill(m, 'inter', ARRAY['L’association du fondaparinux avec des traitements susceptibles d’accroître le risque hémorragique augmente le risque de saignement (voir rubrique 4.4).', 'Les antiagrégants plaquettaires (acide acétylsalicylique), les AINS (piroxicam) et la digoxine n''ont pas modifié les paramètres pharmacocinétiques du fondaparinux.']);
  PERFORM pg_temp.jp_fill(m, 'ei', ARRAY['Le fondaparinux doit être utilisé avec précaution chez les patients ayant un risque accru d’hémorragie (voir rubrique 4.4.).', 'Les effets indésirables les plus fréquents étaient les complications hémorragiques (voir rubrique 4.4).', 'Fréquent : saignement (gastro-intestinal, hématurie, hématome, épistaxis, hémoptysie, hémorragie utérovaginale, hémarthrose, oculaire, purpura, ecchymose)', 'Peu fréquent : anémie, thrombocytopénie.', 'Rare : autres saignements (hépatique, rétropéritonéal, intracrânien/intracérébral) thrombocytopénie', 'Rare : réaction allergique (incluant de très rares cas d’angiœdème, de réaction anaphylactoïde/anaphylactique)']);
  PERFORM pg_temp.jp_fill(m, 'surv', ARRAY['Si l''association ne peut être évitée, une surveillance particulière s''impose.']);

END
